messages.content:
{
 "observed": [
  "Wednesday, February 3, 2016. The newsreader gives the date twice. The depot clerk tears the Tuesday sheet off his timetable.",
  "You are at the radio station. A copy of a received telegram is at your hand: Alma's daughter in Pittsburgh has the whole interview. Her reply is 'I know that voice. Play it again.'"
 ],
 "your_retained_experiences": [
  "Larry records Alma on his last charged take. The reel stays with him.",
  "Larry delivers Alma's reel.",
  "Get the reel to the patch. Done. Let Rita have both takes. Let Phil go to Pittsburgh or not. The lights are on tonight and they'll be on at the party. I don't need to watch them. I just needed one good angle of a woman talking to her daughter and the charge dying in the middle of a sentence. I got it. Now I go home and the reel is not mine anymore, it's the patch's, and I'll drink a beer in the lobby or I won't, and the Rialto will be dark by morning and that's fine. That's how it is."
 ],
 "physical_choices": {
  "keep_own_copy": "Label a personal copy of the transmitted reel.",
  "go_off_duty": "Put the kit away and go off duty.",
  "listen_to_interview": "Listen to the transmitted reel on the radio."
 }
}
